control_patches.generic16:
--- cached24/ikea/include/ikea/tuplepack/read.h
+++ generic16/ikea/include/ikea/tuplepack/read.h
@@ -17,10 +17,9 @@
     // Predicates reuse the projection prepared at binding, avoiding a dependent
     // plan/control load for each encoded comparison. Generic reads retain the
     // shared plan rather than copying its larger native controls.
-    code filter_code_;
     friend class detail::field_predicate<N, Byte, Rows>;
     reader(const read_plan<N, Rows>& plan, const basic_view<Byte>& source)
-        : plan_(&plan), source_(&source), filter_code_(plan.controls().codes[0]) {}
+        : plan_(&plan), source_(&source) {}

   public:
     static constexpr unsigned rows = Rows;
--- cached24/ikea/include/ikea/tuplepack/filter.h
+++ generic16/ikea/include/ikea/tuplepack/filter.h
@@ -30,7 +30,7 @@
                      std::uint64_t active = detail::all_rows<Rows>) const {
         if (!active)
             return 0;
-        const auto& code_ = read_.filter_code_;
+        const auto& code_ = read_.plan().controls().codes[0];
         const unsigned limit = (1u << code_.width) - 1;
         if (rhs > limit)
             return ikea::compare<Op>(0, rhs) ? active : 0;

